pub(super) fn audit<'a>(
    &mut self,
    state: impl Into<sc::RefView<'a>>,
    prefix_len: usize,
    profile: &str,
    rule: &str,
) -> Result<Counts, String> {
    let result = (|| {
        audit_generated_in_store(
            &mut super::audit_store::StoreView::for_audit(&mut self.reader),
            state.into(),
            self.raw.prefix(prefix_len)?,
            profile,
            rule,
            None,
            None,
            Some(&mut self.memo),
            Some(&mut self.source_memo),
            Some(&mut self.fields),
            Some(&mut self.ledger),
        )
    })();
    if result.is_err() {
        self.fields.clear();
        self.ledger.clear();
        self.source_memo.clear();
        self.memo.entries.clear();
    }
    result
}

pub(super) fn payload(
    s: &mut (impl SourceFieldStore + ?Sized),
    object: &Object,
) -> Result<RefValue, String> {
    let p = object.fields.get_admitted(s, "payload_json")?;
    s.lookup_ref(p.view(), &[PathStep::JsonText]).map_err(err)
}

pub(super) fn is_kind(rule: &str, kind: &str) -> bool {
    rule == crate::V3_STRUCTURE_RULE_REVISION
        && (crate::tb02c::KINDS.contains(&kind)
            || crate::tb02e::KINDS.contains(&kind)
            || crate::tb02f::KINDS.contains(&kind))
}

fn insufficient_capacity_err(
    reservation: &MemoryReservation,
    additional: usize,
    available: usize,
    pool: &impl MemoryPool,
) -> DataFusionError {
    resources_datafusion_err!(
        "Failed to allocate additional {} for {} with {} already allocated for this reservation - {} remain available for the total memory pool: {}",
        human_readable_size(additional),
        reservation.registration.consumer.name,
        human_readable_size(reservation.size()),
        human_readable_size(available),
        pool
    )
}

